	cmp	edi, 4
	jl	SHORT $LL4@romMapperK

; 161  :     }
; 162  :     
; 163  :     // bankswitch I/O at port $77, 1st insertion only
; 164  :     // it's very likely though that writes to that port get intercepted by every inserted Korean90 cart, and not just 1
; 165  :     ioPortRegister(0x77, NULL, write, rm);

	push	esi
	push	OFFSET _write
	push	0
	push	119					; 00000077H
	call	_ioPortRegister
	add	esp, 16					; 00000010H

; 166  : 
; 167  :     return 1;

	mov	eax, 1
	pop	edi
	pop	esi
	pop	ebp
	pop	ebx

; 168  : }

	add	esp, 32					; 00000020H
	ret	0
_romMapperKorean90Create ENDP
_TEXT	ENDS
END
